script.source:
const allies = H.zone.allies(actor);
if (!allies.length) return false;
await H.resource.adjust(actor, { resolve: allies.length });
for (const ally of allies) await H.resource.adjust(ally, { resolve: 1 });
await H.chat.postHtml(
  `<strong>${foundry.utils.escapeHTML(actor.name)}</strong> restores <strong>${allies.length} Resolve</strong>; each ally restores <strong>1 Resolve</strong> (Back-To-Back).`,
  actor,
);
